/**
 * Port between NFT-03 (metadata, IPFS) and NFT-04 (mint).
 *
 * Shared verbatim by both branches: do not edit this file in either PR.
 * Changes go through a follow-up PR once both are merged.
 */

/** Category enum of the PreservingArt contract (`enum Category`), same order. */
export const CONTRACT_CATEGORIES = ['Painting', 'Sculpture', 'Craft'] as const;
export type ContractCategory = (typeof CONTRACT_CATEGORIES)[number];

/** Everything the mint needs to call `safeMint`, prepared from a published item. */
export interface PreparedMetadata {
  /** Content `ContentId` (UUID) the token is linked to (D01). */
  readonly contentId: string;
  /** `ipfs://<metadata CID>`, written as the token URI. */
  readonly tokenUri: string;
  /** CID of the pinned metadata JSON. */
  readonly metadataCid: string;
  /** CID of the pinned public preview image, or null when the item has none. */
  readonly imageCid: string | null;
  /** sha256 of the master media file, `0x` + 64 lowercase hex chars (contract `masterHash`). */
  readonly masterHash: string;
  /** Public title, at most 256 UTF-8 bytes (contract `MAX_TITLE_BYTES`). */
  readonly title: string;
  readonly category: ContractCategory;
}

export interface MetadataContext {
  readonly requestId: string;
}

/** Prepares and pins the public metadata of a published item. Idempotent per content snapshot. */
export interface MetadataPublisher {
  prepare(contentId: string, context: MetadataContext): Promise<PreparedMetadata>;
}

/** Nest injection token for the MetadataPublisher implementation. */
export const METADATA_PUBLISHER = Symbol('METADATA_PUBLISHER');
